// null/undefined 항목은 건너뛰고, a가 1이면 n을 대문자로 바꿔 이름 목록을 만든다.
function proc(items) {
  return items
    .filter((item) => item != null)
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

// 쉼표로 나누고 앞뒤 공백을 지운 뒤 빈 값은 버린다.
function f2(text) {
  return text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

module.exports = { proc, f2 };

